INSERT OR IGNORE INTO switch_settings (key, value, updated_at) VALUES ('welcome_text', 'Nintendo Switch修理へのお問い合わせありがとうございます！🎮\n\n画面下のメニューから「仮見積もりを見る」をタップすると、機種・症状を選ぶだけで修理費用の目安を確認できます✨\n\n【対応機種】\n・Nintendo Switch\n・Switch Lite\n・Switch 有機EL\n・Nintendo Switch 2\n\nお急ぎの場合はお電話もどうぞ📞\n📞 050-3202-2843\n（受付時間：10時〜20時）\n\nチャットでのご相談は、そのまま下記をご記入のうえご返信ください😆\n例）\n①機種：Switch 有機EL\n②症状：Joy-conのスティックが勝手に動く\n③ご要望：修理費用が知りたい', datetime('now'));
